guidance.correct_example:
def query(a_sql: str) -> Result[list]:
    b_continue = True
    result: Result[list] = INVALID_RESULT
    try:
        cursor.execute(a_sql)
        rows = cursor.fetchall()
    except sqlite3.OperationalError as e:
        result = Result.failure(f'SQL error: {e}')
        b_continue = False
    if b_continue:
        result = Result.success(rows)
    return result

guidance.incorrect_example:
def query(a_sql: str) -> Result[list]:
    try:
        cursor.execute(a_sql)
        rows = cursor.fetchall()
        return Result.success(rows)
    except sqlite3.OperationalError as e:
        raise RuntimeError(f'SQL failed: {e}')
